/// @docImport 'package:vid2pdf/utils/ffmpeg.dart';
library;

import 'dart:developer';
import 'dart:io';

import 'package:pdf/pdf.dart';
import 'package:pdf/widgets.dart' as pw;

import 'package:vid2pdf/utils/ffmpeg.dart';

/// Join a directory of image files into a PDF file whose path is specified by [outFile].
///
/// Source image files are assumed to exist & been generated by [extractFrames].
///
/// [frameFormat] may be used to specify the image type used when extracting frames.
///
/// [isCancelled] may be provided to abort the conversion; it is checked before each frame is added
/// & again before the PDF is written to disk. Returns `false` if the conversion was cancelled, in
/// which case no file is written.
Future<bool> frames2pdf(
  String sourceDir,
  String outFile, {
  FrameFormat frameFormat = FrameFormat.jpeg,
  bool Function()? isCancelled,
}) async {
  bool cancelled() => isCancelled?.call() ?? false;

  final outPdf = pw.Document();

  final members = await Directory(sourceDir).list().toList();
  log('Found ${members.length} frames');

  final sortedFrames =
      members
          .whereType<File>()
          .where((f) => f.path.toLowerCase().endsWith(frameFormat.extension))
          .toList()
        ..sort((a, b) => a.path.compareTo(b.path));
  log('Sorted ${sortedFrames.length} matching frames');

  for (File f in sortedFrames) {
    // Async read yields to the event loop between frames, allowing a cancellation to be processed
    if (cancelled()) {
      return false;
    }
    final img = pw.MemoryImage(await f.readAsBytes());

    outPdf.addPage(
      pw.Page(
        pageFormat: PdfPageFormat.a4.landscape,
        orientation: pw.PageOrientation.landscape,
        margin: pw.EdgeInsets.all(0),
        build: (pw.Context ctx) {
          return pw.Center(child: pw.Image(img));
        },
      ),
    );
  }

  final pdfBytes = await outPdf.save();
  if (cancelled()) {
    return false;
  }

  await File(outFile).writeAsBytes(pdfBytes);
  return true;
}
